import React, { useState } from "react";
import { useHistory } from "react-router-dom";
import "./adminPortfolio.css";

const AdminPortfolio = () => {
  const history = useHistory();
  const [isSettingsMenuVisible, setIsSettingsMenuVisible] = useState(false);

  const handleSettingsClick = () => {
    setIsSettingsMenuVisible(prevState => !prevState);
  };

  const handleMenuOptionClick = (option) => {
    setIsSettingsMenuVisible(false); // Hide menu after click
    switch (option) {
      case "Theme":
        alert("Change Theme clicked");
        break;
      case "Sign Out":
        alert("Sign Out clicked");
        // Implement actual sign out functionality here
        break;
      case "Previous Orders":
        history.push("/previous-orders");
        break;
      default:
        break;
    }
  };

  const handleEditClick = (id) => {
    alert(`Edit clicked for ID: ${id}`);
    // Implement actual edit functionality here
  };

  const handleDeleteClick = (id) => {
    if (window.confirm(`Are you sure you want to delete ID: ${id}?`)) {
      alert(`Delete clicked for ID: ${id}`);
      // Implement actual delete functionality here
    }
  };

  const handleViewClick = (id) => {
    alert(`View clicked for ID: ${id}`);
    // Implement actual view functionality here
  };

  return (
    <div>
      {/* Header */}
      <header>
        <button id="back-button" onClick={() => history.goBack()}>Back</button>
        <h1>Admin Portfolio</h1>
        <button 
          id="settings" 
          onClick={handleSettingsClick}
          aria-expanded={isSettingsMenuVisible} 
          aria-controls="settings-menu"
        >
          Settings
          <span className="settings-menu-button">&#9662;</span> {/* Dropdown arrow */}
        </button>
        <div 
          id="settings-menu"
          className={`settings-menu ${isSettingsMenuVisible ? "visible" : ""}`}
        >
          <ul>
            <li><a href="#theme" onClick={() => handleMenuOptionClick("Theme")}>Theme</a></li>
            <li><a href="#signout" onClick={() => handleMenuOptionClick("Sign Out")}>Sign Out</a></li>
            <li><a href="#previous-orders" onClick={() => handleMenuOptionClick("Previous Orders")}>Previous Orders</a></li>
          </ul>
        </div>
      </header>

      {/* Main Content */}
      <main>
        <div className="table-container">
          {/* Users Table */}
          <section>
            <h2>List of Users</h2>
            <div className="table-wrapper">
              <table>
                <thead>
                  <tr>
                    <th>User ID</th>
                    <th>Name</th>
                    <th>Project Description</th>
                    <th>Status</th>
                    <th>Action</th>
                  </tr>
                </thead>
                <tbody>
                  <tr>
                    <td>1</td>
                    <td>John Doe</td>
                    <td>Project Alpha</td>
                    <td>Active</td>
                    <td>
                      <button className="button edit-btn" onClick={() => handleEditClick(1)}>Edit</button>
                      <button className="button delete-btn" onClick={() => handleDeleteClick(1)}>Delete</button>
                      <button className="button view-btn" onClick={() => handleViewClick(1)}>View</button>
                    </td>
                  </tr>
                  {/* Add more rows as needed */}
                </tbody>
              </table>
            </div>
          </section>
        </div>

        <div className="table-container">
          {/* Builders Table */}
          <section>
            <h2>List of Builders</h2>
            <div className="table-wrapper">
              <table>
                <thead>
                  <tr>
                    <th>Builder ID</th>
                    <th>Name</th>
                    <th>Sites</th>
                    <th>Status</th>
                    <th>Action</th>
                  </tr>
                </thead>
                <tbody>
                  <tr>
                    <td>1</td>
                    <td>Builder Inc.</td>
                    <td>Site A</td>
                    <td>Active</td>
                    <td>
                      <button className="button edit-btn" onClick={() => handleEditClick(1)}>Edit</button>
                      <button className="button delete-btn" onClick={() => handleDeleteClick(1)}>Delete</button>
                      <button className="button view-btn" onClick={() => handleViewClick(1)}>View</button>
                    </td>
                  </tr>
                  {/* Add more rows as needed */}
                </tbody>
              </table>
            </div>
          </section>
        </div>

        {/* Footer Buttons */}
        <div className="footer-buttons">
          <button className="button confirm-btn">Confirm</button>
          <button className="button otp-btn">OTP</button>
        </div>
      </main>
    </div>
  );
};

export default AdminPortfolio;
